def transform(grid):
    """Set the dominant color to 0 and replace the minority color with the original dominant color."""
    counts = Counter(cell for row in grid for cell in row)
    background = counts.most_common(1)[0][0]
    return [[0 if cell == background else background for cell in row] for row in grid]
